/**
 * Case-insensitive substring match. `%`, `_` and `\` are literal characters;
 * SQLite only treats them as wildcards when the pattern does not escape them.
 */
function literalSubstring(query: string) {
  const escaped = query.replace(/[\\%_]/g, (character) => `\\${character}`);
  return sql`${searchIndex.content} LIKE ${`%${escaped}%`} ESCAPE '\\'`;
}

