/** Writes a live subject back, or drops it when it is missing or archived. */
async function reindexSubject(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  if (subjectKind === "issue") {
    const issue = await issueRepo.findIssueById(orgId, subjectId as IssueId);
    if (!issue || issue.archivedAt !== null) {
      await removeFromIndex(orgId, "issue", subjectId);
      return;
    }
    await indexIssue(orgId, issue);
    return;
  }

  if (subjectKind === "comment") {
    const comment = await commentRepo.findCommentById(orgId, subjectId as CommentId);
    if (!comment || comment.archivedAt !== null) {
      await removeFromIndex(orgId, "comment", subjectId);
      return;
    }
    await indexComment(orgId, comment);
    return;
  }

  const project = await projectRepo.findProjectById(orgId, subjectId as ProjectId);
  if (!project || project.archivedAt !== null) {
    await removeFromIndex(orgId, "project", subjectId);
    return;
  }
  await indexProject(orgId, project);
}

/** Comments carry their issue's project, so an issue move rewrites them too. */
async function reindexCommentsForIssue(orgId: OrgId, issueId: IssueId): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: false,
      limit: 100,
      cursor,
    });
    for (const comment of page.items) {
      await indexComment(orgId, comment);
    }
    cursor = page.nextCursor;
  } while (cursor !== null);
}

